/* Types */
/**  运行中 phase 状态（线面）。 */
export type ActivePhase = {
	phase: string,
	attempt: number,
	startAt: string | null,
};

/**  统一视图活面投影 */
export type ActiveRunView = {
	runId: string,
	status: ChangeRunStatus,
	phase: string | null,
	attempt: number | null,
	ask: AskPayload | null,
	/**  归档前停等点的前置只读载荷（非该停等点恒 null；停等面数据面） */
	archive: ArchivePreflight | null,
	startedAt: string,
	nodes: ChangeStepState[],
	edges: ChangeRunEdgeRecord[],
};

/**  消息内块：Text / Thinking / ToolUse / ToolResult 四变体（tag `kind`，camelCase）。 */
export type AgentBlock = 
/**  文本块（assistant 正文 / user 输入） */
{ kind: "text"; text: string } | 
/**  思考块 */
{ kind: "thinking"; thinking: string } | 
/**  工具调用块（`input` 为原 JSON，结构由具体工具自解释） */
{ kind: "toolUse"; id: string; name: string; input: unknown } | 
/**  工具结果块（`content` 已扁平化为字符串；`is_error` 缺失视作 false） */
{ kind: "toolResult"; id: string; content: string; isError: boolean };

/**  token 级增量载荷（思考/回复可辨；serde 内部 tag camelCase，与块模型同式）。 */
export type AgentDelta = 
/**  文本增量 */
{ kind: "text"; text: string } | 
/**  思考增量 */
{ kind: "thinking"; thinking: string };

/**
 *  agent 实例引擎二值（agent 管理域，store 本地枚举）：serde camelCase 线值
 *  `"cli" | "sdk"` 与门面 `EngineKind` 同线值域。持久化的是配置值域而非引擎
 *  实现——store 禁拖引擎门面 crate（零新增依赖），`AgentEngineKind` →
 *  `EngineKind` 映射收运行发起解析单点（两臂 match）。**变体集与 bincode
 *  序号（`Cli`=0 / `Sdk`=1）为解码锚，MUST NOT 增删重排**（删/重排即
 *  `AgentInstanceRecord` + `SessionRecord` 两表报废含 sdk 数据）。
 */
export type AgentEngineKind = 
/**
 *  本机 claude CLI 租户（解码兼容，不再可选：写入面与运行发起解析均拒，
 *  存量行只读；bincode 序号 0 永久保留为历史数据解码锚）
 */
"cli" | 
/**  进程内 sdk 租户（唯一活档） */
"sdk";

/**
 *  统一事件信封：每事件携带 `seq`（单调序号，入库排序键）与时间戳；
 *  `kind` 扁平进线格式（线格式 = 落库形态（密封） = 前端 DTO 基准）。
 */
export type AgentEvent = {
	/**  单调序号，会话级续排 */
	seq: number,
	/**  事件盖戳时刻（UTC unix 毫秒） */
	timestampMs: number,
} & AgentEventKind;

export type AgentEventKind = 
/**  run 启动（源自 system/init）：模型、会话、工具与 MCP 服务器清单 */
{ kind: "runStarted"; model: string | null; sessionId: string | null; tools: string[]; mcpServers: string[] } | 
/**
 *  token 级增量（ephemeral）：只上传输面，store 永不见；配对键沿用
 *  `parent_tool_use_id` 词汇（子代理归因一处两用）
 */
{ kind: "messageDelta"; parentToolUseId: string | null; delta: AgentDelta } | 
/**  对话消息（user 言语 / assistant 回应 / tool 结果管道） */
{ kind: "message"; role: AgentMessageRole; blocks: AgentBlock[]; parentToolUseId: string | null } | 
/**  system 通知（permission_denial / api_retry 等，subtype 不做封闭枚举） */
{ kind: "systemNotice"; subtype: string; payload: unknown } | 
/**
 *  轮收敛事件：唯一驱动状态机收敛的变体，字段面 = 统计唯一口径（由内核
 *  收口写轮行，引擎无第二口径）
 */
{ kind: "turnDone"; subtype: string; isError: boolean; numTurns: number | null; durationMs: number | null; costUsd: number | null; usage: unknown; sessionId: string | null } | 
/**  未识别事件透传（未知 type / 非 JSON 行）：原文完整保留 */
{ kind: "raw"; eventType: string; rawJson: string };

/**
 *  agent 实例记录（agent 管理域，user 维度落全局库）：引擎选择（线值
 *  `cli` | `sdk` 双值保留，写入面仅收 `sdk`——存量 cli 行可读可删不可改）
 *  与 provider 引用（`sdk` 必填且引用存在；「cli 可空」语义随 CLI 租户退役，
 *  存量 cli 行 provider 可空只读保留）+ 默认标记（全局恒至多一；写入只发生
 *  在 store 的 `set_default_agent_instance` 与删除清标记两处，upsert 不参与
 *  写；默认标记仅可落 sdk 实例）。
 */
export type AgentInstanceRecord = {
	/**  记录 id（主键，写事务内 max+1 分配；后续 workspace 关联引用锚点） */
	id: number,
	/**  展示名（唯一 = 写事务内查重） */
	name: string,
	/**  引擎二值（cli / sdk；映射到门面 `EngineKind` 收运行发起解析单点） */
	engine: AgentEngineKind,
	/**
	 *  引用 provider id（同库 [`AgentProviderRecord`] 主键；`sdk` 必填且引用
	 *  存在——`sdk` 唯一活档，存量 `cli` 行可空只读保留）
	 */
	providerId: number | null,
	/**  默认标记（缺省运行解析入口；全局恒至多一） */
	isDefault: boolean,
};

export type AgentMessageRole = 
/**  用户言语 */
"user" | 
/**  模型回应 */
"assistant" | 
/**  引擎工具结果 */
"tool";

/**
 *  provider 三档模型档位（agent 管理域，纯嵌套 struct 不落独立模型——嵌装
 *  先例同转录单表的 `AgentEvent`）：high / medium / low 三档
 *  模型标识，运行发起解析消费固定取 high 档（effort 进 run 参数与档位选择
 *  器为后续迭代，本期只存不选）。
 */
export type AgentModelTiers = {
	high: string,
	/**  medium 档模型标识（本期只存不选） */
	medium: string,
	low: string,
};

/**
 *  permission-mode 三档；无头模式下档位决定工具审批行为（档位语义由能力
 *  spec 留痕，本 crate 不解释）。
 */
export type AgentPermissionMode = 
/**  CLI 默认档（需审批工具在无头下直接被拒） */
"default" | 
/**  自动接受文件编辑 */
"acceptEdits" | 
/**  跳过全部审批（调试页默认档） */
"bypassPermissions";

/**  agent provider 记录 */
export type AgentProviderRecord = {
	/**  记录 id（主键，写事务内 max+1 分配） */
	id: number,
	/**  展示名（唯一 = 写事务内查重） */
	name: string,
	/**  openai 兼容端点 base_url（含版本段，如 `https://…/v1`） */
	baseUrl: string,
	/**  认证凭据（bearer token，明文） */
	apiKey: string,
	/**  三档模型标识（运行发起解析消费固定取 high 档） */
	models: AgentModelTiers,
	/**
	 *  provider 上下文窗长（token 数；sdk 引擎上下文防线消费）：可空列，
	 *  `None` = 未配置（缺省走 128K 启发式；编辑语义留空 = 未配置，MUST NOT
	 *  落 0 或缺省字面）
	 */
	contextLength?: number | null,
};

/**
 *  `agent_start` Channel 的消息信封（app 层 IPC 类型，非 core 契约）：实时
 *  事件与终态轮行双变体，tag `ipc` 判别（TS 镜像放 transport，camelCase
 *  对齐）。信封不含 record 语义——终态轮行塞进事件 usage 是反模式。
 */
export type AgentRunMessage = 
/**  实时事件（落库与流出同源同构） */
{ ipc: "event"; event: AgentEvent } | 
/**  终态轮行（提前 resolve 契约的终态流出半边，与重放两路同构） */
{ ipc: "record"; record: TurnSummary };

/**
 *  run 状态四档（落库 / 出线契约）：与 [`crate::state::AgentRunState`] 状态机
 *  内存态两型并存——本枚举是 serde camelCase 线格式与 store 落库形态的值域
 *  契约，状态机类型不出契约面（编排侧显式 `match` 映射）。
 */
export type AgentRunStatus = 
/**  运行中（轮 begin 落库行初值） */
"running" | 
/**  正常收敛（TurnDone 事件 is_error=false） */
"completed" | 
/**  失败收敛（TurnDone 事件 is_error=true / 无 TurnDone 异常终止 / 落库失败） */
"failed" | 
/**  用户主动终止收敛（stop 显式请求，语义区别于引擎失败） */
"stopped";

/**  archive 月份分组；`month` 为 `None` 即"未知时间"组，固定排组序列尾。 */
export type ArchiveGroup = {
	month: string | null,
	changes: ChangeSummary[],
};

/**  归档产出（IPC DTO）。 */
export type ArchiveOutcome = {
	name: string,
	/**  归档日期 UTC `YYYY-MM-DD`（本日；续半边命中带前缀目录时取前缀日期） */
	archivedDate: string,
};

/**
 *  归档前置只读载荷（store 读 + vcs 探测的聚合像）：归档相位前的停等面数据面，
 *  随 `RunUpdate::ConfirmWait` / `ChangeRunSnapshot` 出线（进程内，不落库）；
 *  归档相位的 Preflight 步以同一函数重算并交 `PhaseCursor` 供后续步消费。
 */
export type ArchivePreflight = {
	name: string,
	/**
	 *  完成度结论（workflow 相位表全相位 non-stale pass / skipped；无相位表恒
	 *  false——警告词汇单点承载）
	 */
	completed: boolean,
	/**  未过相位清单（workflow_type 不受支持时为空——不可核算） */
	incompletePhases: string[],
	/**  缺席产物文档（proposal.md / design.md / tasks.md 子集） */
	missingArtifacts: string[],
	/**  delta specs capability 清单（定位目录 specs/ 子树非空者） */
	deltaSpecs: string[],
	/**  worktree 记录（None = legacy 主 root change） */
	worktree: string | null,
	/**  change 分支名（worktree 记录在场才在案：`change/<name>`） */
	branch: string | null,
	/**  主仓当前分支名（合入目标；worktree 记录在场才探测） */
	mergeTarget: string | null,
};

/**
 *  产物寻址清单项：`source` 为 change 内相对 POSIX 路径或 eval 条目序号串；
 *  `phase` 为**清单归属**（文件候选 = 清单声明相位；eval 候选 = PhaseRecord 投影
 *  的相位）——前端按本归属挂列，MUST NOT 重建第二份静态映射表。
 */
export type ArtifactDescriptor = {
	kind: string,
	source: string,
	title: string,
	/**  phase 归属（清单声明 / PhaseRecord 投影供给） */
	phase: string,
};

/**  中间产物信封：所有产物以统一形状经 IPC 传递。 */
export type ArtifactEnvelope = {
	/**  契约 ID（如 "eval-checklist"），前端据此路由 renderer */
	kind: string,
	/**  产物格式版本 */
	version: number,
	title: string,
	/**  kind 自描述结构化负载 */
	payload: unknown,
	/**  渲染器缺席时的保底文本 */
	fallbackText: string | null,
};

/**  ask 载荷：决策会话 ask 动作的中断问题与候选选项。 */
export type AskPayload = {
	question: string,
	options: string[],
};

/**
 *  单次尝试记录：backtrack 目标与原因随条目可查；会话槽位（executor /
 *  evaluator / decision）自 PhaseRecord 三槽位列直读透出，无槽位字段三值均
 *  `null`。
 */
export type AttemptRecord = {
	attempt: number | null,
	verdict: Verdict,
	report: string,
	checklist: ChecklistItem[],
	skipped: boolean,
	stale: boolean,
	startAt: string | null,
	timestamp: string | null,
	backtrackTo: string | null,
	backtrackReason: string | null,
	executorSessionId: string | null,
	evaluatorSessionId: string | null,
	decisionSessionId: string | null,
};

/**
 *  change 详情聚合。`id` 为身份锚（寻址入参同值）；`name` 自记录直读（恒裸名
 *  ——归档 change 的日期前缀仅存在于磁盘目录名，MUST NOT 进入出线值）；db 无
 *  该 id 记录 → 详情整体不可达（`None`，未知 id 语义）。
 */
export type ChangeDetail = {
	/**  change 身份锚（uuid 形态） */
	id: string,
	/**  change 名（自记录直读，恒裸名） */
	name: string,
	/**  人类可读标题，恒非空（自记录直读，见 desktop-change-state-store） */
	title: string,
	source: ChangeSource,
	status: ChangeStatus | null,
	created: string | null,
	pipeline: PhaseEntry[],
	activePhase: ActivePhase | null,
	/**
	 *  run 执行图全量读面（unify-run-state-persistence + run-workflow-by-step：
	 *  全史不截，runs 按 `started_at` 升序、nodes 按 emit 序、edges 按 emit 序；
	 *  未建档 / 未跑形态恒空数组）
	 */
	runs: ChangeRunEntry[],
	artifacts: ArtifactDescriptor[],
	/**
	 *  本 change 的 worktree 绝对路径（自建档记录直读透出，None → null；
	 *  legacy 记录不渲染——路径为刻意出线的执行锚，review / merge 可达）
	 */
	worktree: string | null,
};

/**
 *  统一视图信封：库读史 ∪ 在飞 run 活面一次返回（前端零双命令拼接；
 *  `active_run` 终态即除名 → null 语义不变）。
 */
export type ChangeDetailUnified = {
	detail: ChangeDetail,
	activeRun: ActiveRunView | null,
};

/**  change 列表：active 全量 + archive 按月分组。 */
export type ChangeList = {
	active: ChangeSummary[],
	archiveGroups: ArchiveGroup[],
};

/**  run 执行图边行线面（四 kind 封闭集直出；端点 = 节点身份串）。 */
export type ChangeRunEdgeRecord = {
	fromNodeKey: string,
	toNodeKey: string,
	edgeKind: RunEdgeKind,
};

/**
 *  单次 run 执行图条目（全史不截；在飞 run 的 start 行已在库——status=
 *  running、nodes / edges 恒空，run 清单面运行中可见）。
 */
export type ChangeRunEntry = {
	runId: string,
	status: RunStatus,
	reason: string | null,
	startedAt: string | null,
	finishedAt: string | null,
	/**  执行图节点（全词汇零过滤，node_seq 升序 = emit 序） */
	nodes: ChangeRunNodeRecord[],
	/**  执行图边（四 kind，edge_seq 升序 = emit 序） */
	edges: ChangeRunEdgeRecord[],
};

/**
 *  run 执行图节点行线面（十九值全词汇封闭集直出，词汇 = `state::RunStepKind`
 *  单点；稳定身份键 `(phase, attempt, step, instanceNo)`，库读序 = node_seq 升序
 *  = emit 序）。
 */
export type ChangeRunNodeRecord = {
	phase: string,
	attempt: number,
	step: RunStepKind,
	/**  同 `(phase, attempt, step)` 内的执行实例号（feedback 重跑递增） */
	instanceNo: number,
	status: RunStepStatus,
	sessionId: string | null,
	detail: string | null,
	/**  全量输出引用（`ExecOutput::Recorded { exec_id }`；无记录恒 null） */
	outputRef: string | null,
};

/**
 *  run 状态六档（camelCase 线格式）：三态运行期（running / 两类停等）与
 *  三态终局（completed / stopped / failed）。
 */
export type ChangeRunStatus = 
/**  运行中 */
"running" | 
/**  phase 间停等用户确认 */
"waitingConfirm" | 
/**  ask 中断，等待自由文本应答 */
"waitingAsk" | 
/**  全相位（含 archive 相位）pass 走完 */
"completed" | 
/**  受控终止（用户停止 / confirm=false / 决策 stop 动作） */
"stopped" | 
/**  失败终止（写面 / 会话失败 / 决策解析失败显式停给用户） */
"failed";

/**
 *  发起提前 resolve 返回值：run_id 立即可知，运行态经 Channel 流出（与
 *  agent_start 提前 resolve 契约同型）。
 */
export type ChangeRunSummary = {
	runId: string,
	status: ChangeRunStatus,
};

/**  change 来源：进行中 / 已归档（自 db status 派生）。 */
export type ChangeSource = "active" | "archive";

/**  change 状态二值（线格式小写词；queries DTO 直接复用本类型）。 */
export type ChangeStatus = 
/**  进行中（建档后默认态） */
"active" | 
/**  已归档（写面 archive 翻转） */
"archived";

/**
 *  步词汇（四类节点可辨）：WorkerAgent 步（executor / evaluator / decision /
 *  spec-sync / resolve-conflicts）+ 相位机 / 工具步（phase-start / phase-log /
 *  static-check / test-execution / mutation-test / preflight / seal）+ Git 步
 * （commit / rebase / merge / finalize）+ Gate 三门。
 */
export type ChangeStepKind = 
/**  executor 会话 */
"executor" | 
/**  evaluator 会话 */
"evaluator" | 
/**  决策会话 */
"decision" | 
/**  phase-start 相位机步 */
"phaseStart" | 
/**  static-check 工具步 */
"staticCheck" | 
/**  test-execution 门禁工具步（确定性测试执行链，绿跑零 agent） */
"testExecution" | 
/**  mutation-test 门禁工具步（确定性突变执行链，独立反馈边②） */
"mutationTest" | 
/**  phase-log 相位机步 */
"phaseLog" | 
/**  verdict 解析门 */
"verdictGate" | 
/**  retry 预算门（phase-next 重试 / 上限分叉） */
"retryGate" | 
/**  backtrack 白名单门（决策越权预校验） */
"whitelistGate" | 
/**  归档前置只读校验步（内联步） */
"preflight" | 
/**  归档 worktree 提交步（vcs） */
"commit" | 
/**  归档分支重放步（vcs） */
"rebase" | 
/**  归档合入冲突解算步（agent 会话；条件执行） */
"resolveConflicts" | 
/**  归档主仓快进步（vcs） */
"merge" | 
/**  归档 delta specs 同步步（agent 会话） */
"specSync" | 
/**  归档双写收口步（内联步） */
"seal" | 
/**  归档落盘提交步（vcs） */
"finalize";

/**
 *  步状态行：一次 `RunUpdate::Step` 的载荷，运行步节点推导的唯一输入面。稳定
 *  身份键 = `(phase, attempt, step, instance_no)`——同 `(phase, attempt, step)` 的
 *  多次执行（feedback 重跑）以 `instance_no` 递增区分，前端直读直渲染。
 */
export type ChangeStepState = {
	/**  相位 id */
	phase: string,
	/**  attempt 号 */
	attempt: number,
	/**  步词汇 */
	step: ChangeStepKind,
	/**  同 `(phase, attempt, step)` 内的执行实例号（每次执行递增） */
	instanceNo: number,
	/**  步状态 */
	status: ChangeStepStatus,
	/**  WorkerAgent 步所属会话 id（工具步 / Gate 步为 None） */
	sessionId: string | null,
	/**  人读详情（失败记因 / 通过摘要） */
	detail: string | null,
	/**  全量输出引用（`ExecOutput::Recorded { exec_id }`；Transient 恒 None） */
	outputRef: string | null,
};

/**  步状态四档。 */
export type ChangeStepStatus = 
/**  步进行中（节点 pulse 运行态） */
"running" | 
/**  步通过 */
"passed" | 
/**  步失败（图上红节点） */
"failed" | 
/**  步因停止 / 终止收敛（非失败语义） */
"stopped";

/**
 *  列表条目摘要。`id` 为身份锚（行键 / 前端路由 / 一切后续寻址），`name` 恒
 *  裸名、`title` 为人类可读标题（恒非空，渲染标题面）；条目集合 db 单源，
 *  状态面恒在场（`Option` 形态保留——非档案缺位语义）。
 */
export type ChangeSummary = {
	/**  change 身份锚（uuid 形态） */
	id: string,
	/**  change 名（恒裸名——归档日期前缀仅存在于磁盘目录名，MUST NOT 出线） */
	name: string,
	/**  人类可读标题，恒非空（自记录直读，见 desktop-change-state-store） */
	title: string,
	source: ChangeSource,
	status: ChangeStatus | null,
	activePhase: ActivePhase | null,
	created: string | null,
};

/**  checklist 检查项。 */
export type ChecklistItem = {
	item: string,
	pass: boolean,
	evidence: string,
};

/**
 *  工作区代码统计报告（三面聚合根）：同一次 `Languages::get_statistics` 解析
 *  的三种投影——汇总合计 / 逐语言行 / 目录树（目录节点 + 文件叶混合条目），
 *  三面数字互洽。
 */
export type CodeStatsReport = {
	/**  全部被解析文件合计 */
	totals: CodeTotals,
	/**  逐语言统计（按代码行降序，tie 语言名字典序） */
	languages: LanguageStats[],
	/**  树（≤ depth 级目录节点 + 深度内文件叶；根层直属文件为顶层文件叶） */
	tree: TreeEntry[],
};

/**  汇总面四项总量；`lines` 不设字段（派生值 `code + comments + blanks` 前端可算）。 */
export type CodeTotals = {
	/**  被识别文件数 */
	files: number,
	/**  代码行合计 */
	code: number,
	/**  注释行合计 */
	comments: number,
	/**  空行合计 */
	blanks: number,
};

/**
 *  单条诊断：`path` 为点路径（文件级 `$`，suite 内形如
 *  `tests[0].coverage.lines`），`message` 为中文人读文案（含违例原值与
 *  所落默认值）。
 */
export type ConfigDiagnostic = {
	/**  诊断类别 */
	kind: DiagnosticKind,
	/**  违例 / 吃默认字段的点路径 */
	path: string,
	/**  中文人读文案 */
	message: string,
};

/**  顶层未知字段 passthrough 载体：key + 原文值原样保留、无诊断。 */
export type ConfigExtraField = {
	/**  未知字段名 */
	key: string,
	/**  原文值（嵌套形态无损保留；出线 TS `unknown`） */
	value: unknown,
};

/**
 *  覆盖率阈值（百分点 0–100）：三阈值恒有值——文件显式设值原样保留，
 *  未设 / 非法吃默认（80 / 70 / 75）。
 */
export type CoverageThresholds = {
	/**  行覆盖率阈值（默认 80） */
	lines: number | null,
	/**  分支覆盖率阈值（默认 70） */
	branches: number | null,
	/**  函数覆盖率阈值（默认 75） */
	functions: number | null,
};

/**
 *  创建产出（IPC DTO）：本次铸出的 change id（身份锚——前端导航 / 一切后续
 *  寻址入参）、名称、创建日期、worktree 绝对路径（刻意出线的执行锚——review /
 *  手动 commit / merge 可达）与警告清单（脏仓 / bootstrap 注记，持久入 DTO
 *  抵达前端行内呈现）。
 */
export type CreateOutcome = {
	/**  本次铸出的 change id（uuid v7 形态；库内记录同值逐字一致） */
	id: string,
	name: string,
	/**
	 *  UTC 日历日期 `YYYY-MM-DD`（取 db 建档 `created_at`，写面铸出后随 DTO
	 *  直达命令返回，无需回读）
	 */
	created: string,
	/**  本 change 分配的 worktree 绝对路径（执行锚；db 记录同源） */
	worktree: string,
	/**  警告清单（脏仓引导 / 依赖引导注记与失败；干净仓且顺利 → 空清单） */
	warnings: string[],
};

/**
 *  数据维度（信封维度标签 + db 查看命令 scope 入参双职）：`User` 全局库 /
 *  `Workspace` workspace 库。serde 线值为 `"user"` / `"workspace"`。
 */
export type DbDimension = 
/**
 *  user 维度（全局库，`WorkspaceRecord` 与 agent 管理两模型——user 维度
 *  已落地代表，desktop-data-dimensions 留痕）
 */
"user" | 
/**
 *  workspace 维度（per-workspace 库，轮统计行 / 会话 / 转录 / explore /
 *  change 流程状态 + run 运行史十模型）
 */
"workspace";

/**
 *  诊断类别（前端状态面映射口径）：`fileMissing` → 空态；
 *  `readFailed` / `jsonInvalid` → inline 错误；`invalidValue` /
 *  `defaultApplied` → 警示区条目。
 */
export type DiagnosticKind = 
/**  配置文件不存在（多数 workspace 常态，空态来源、非错误） */
"fileMissing" | 
/**  配置文件存在但不可读（inline 错误来源） */
"readFailed" | 
/**  JSON 语法非法（inline 错误来源） */
"jsonInvalid" | 
/**  字段违例（已按规则处置） */
"invalidValue" | 
/**  字段未设、吃默认值 */
"defaultApplied";

/**
 *  目录树节点：统计为该目录子树内**全部**被解析文件合计（祖先链逐级累计，
 *  含更深文件）；`path` 为相对 root 的 POSIX 路径（`/` 分隔，Windows 下
 *  tokei 报告的分隔符混排经 components 归一化）；`children` 为直接子目录 +
 *  直接文件叶（目录先于文件，各自按 `name` 字典序）。
 */
export type DirNode = {
	/**  末段目录名 */
	name: string,
	/**  相对 root 的 POSIX 路径（`/` 分隔） */
	path: string,
	/**  子树内被识别文件数 */
	files: number,
	/**  子树内代码行合计 */
	code: number,
	/**  子树内注释行合计 */
	comments: number,
	/**  子树内空行合计 */
	blanks: number,
	/**  直接子目录与直接文件叶（≤ depth 截断；目录在前、文件在后，各按 name 字典序） */
	children: TreeEntry[],
};

/**  单篇 explore 笔记内容（纯文本 DTO，命令层直出，不套 change 域产物信封）。 */
export type ExploreDoc = {
	/**  笔记名（= 文件 stem） */
	name: string,
	/**  UTF-8 文本内容 */
	content: string,
};

/**  explore 清单记录 */
export type ExploreRecord = {
	/**  记录 id（主键，写事务内 max+1 分配；身份与文件名解耦） */
	id: number,
	/**  workspace 归属（canonical root，与 `WorkspaceRecord.root` 同口径） */
	root: string,
	/**  笔记文件 stem 寻址键（kebab-case 口径） */
	name: string,
	/**
	 *  人类可读标题，恒非空（创建与升级默认 = `name`，agent 产出笔记首行
	 *  `# <标题>` 后经 `set_explore_title` 回填覆盖）
	 */
	title: string,
	/**
	 *  工作流类型（合法值 `requirement` | `test-only`；创建与升级默认 =
	 *  `requirement`，agent 推算类型经 `set_explore_workflow_type` 回填覆盖）
	 */
	workflowType: string,
	/**  指向已 promote 的 **change id** 身份锚；`None` = 草稿态 */
	promotedTo: string | null,
	/**
	 *  归属 agent 会话 id（建档同事务预建空会话并回写；存量记录经
	 *  `ensure_explore_session` 归位补齐；None = 尚无会话归属）
	 */
	sessionId: string | null,
	/**  建档时间（UTC unix 毫秒） */
	createdAt: number,
	/**  最近更新时间（UTC unix 毫秒） */
	updatedAt: number,
};

/**  导入扫描条目：stem 名称 + 可得的修改时间。 */
export type ExploreScanEntry = {
	/**  笔记名（= 文件 stem） */
	name: string,
	/**  修改时间（UTC unix 毫秒）；metadata 不可得时为 `None` */
	modifiedAt: number | null,
};

/**
 *  文件叶节点：单个被解析文件的行统计；父目录在深度内时挂其 `children`
 *  （目录级数 0 = 根层直属文件挂树顶层），深度外的文件不出叶（仅并入祖先聚合）。
 */
export type FileNode = {
	/**  文件名（含扩展名） */
	name: string,
	/**  相对 root 的 POSIX 路径（`/` 分隔） */
	path: string,
	/**  代码行 */
	code: number,
	/**  注释行 */
	comments: number,
	/**  空行 */
	blanks: number,
};

/**  桥接后的前端信号载荷（与 `FileWatchSignal` 同构，camelCase；无内容字节）。 */
export type FileWatchEvent = {
	/**  被修改目标的订阅路径 */
	path: string,
};

/**
 *  单语言统计行：`name` 取 tokei `LanguageType::name()`；`share` 为代码行份额
 *  （该语言 code / Σ全部语言 code，百分点 0–100；Σcode 为 0 时 0.0）。
 */
export type LanguageStats = {
	/**  语言名（tokei 识别名，如 "Rust" / "Markdown"） */
	name: string,
	/**  该语言被识别文件数 */
	files: number,
	/**  代码行 */
	code: number,
	/**  注释行 */
	comments: number,
	/**  空行 */
	blanks: number,
	/**  代码行份额（百分点 0–100，与排序键同轴） */
	share: number | null,
};

/**  模型清单一行：模型名 + 记录计数（计数 0 也列出）。 */
export type ModelInfo = {
	/**  模型名（查看器展示与 `Store::scan` 入参同源） */
	name: string,
	/**  记录计数 */
	count: number,
};

/**  变异测试配置：`score` 恒有值（未设 / 非法吃默认 70）；`cwd` 无默认。 */
export type MutationConfig = {
	/**  突变执行目录（相对 root；未设为 `None`，由消费者按 LCA 计算） */
	cwd: string | null,
	/**  变异测试得分阈值（默认 70） */
	score: number | null,
};

/**  一站流水线：该 phase 的全部 attempt 序列。 */
export type PhaseEntry = {
	phase: string,
	attempts: AttemptRecord[],
};

/**
 *  promote 产出（IPC DTO）：本次铸出的 change 身份锚（前端跳转 / 一切后续寻
 *  址入参）与 change 名（= explore name，promote 免转换语义的显式呈现）。
 */
export type PromoteOutcome = {
	/**  本次铸出的 change id（uuid v7 形态；库内记录同值逐字一致） */
	changeId: string,
	/**  change 名（= explore 记录 name，恒裸名） */
	changeName: string,
};

/**  记录信封：key / value 均为 JSON 值（native_db 类型不越信封，无二进制）。 */
export type RecordEnvelope = {
	/**  记录主键的 JSON 形态 */
	key: unknown,
	/**  记录本体（serde 转 JSON 值） */
	value: unknown,
};

/**
 *  分页信封：offset / limit 区间记录 + 该模型全量计数（二者同一读事务
 *  快照——并发写下页界与行集自洽，`total` 是页界唯一事实源）。
 */
export type RecordsPage = {
	/**  区间记录信封 */
	records: RecordEnvelope[],
	/**  该模型全量计数 */
	total: number,
};

/**  自定义规则配置，按工作流阶段分组；子字段为字符串列表或未设。 */
export type RulesConfig = {
	/**  提案阶段的自定义规则列表（未设为 `None`） */
	proposal: string[] | null,
	/**  任务阶段的自定义规则列表（未设为 `None`） */
	tasks: string[] | null,
};

/**
 *  run 执行图边词汇封闭集（四值，线格式小写词）：`forward` 计划序推进 /
 *  `feedback` gate 失败回同 phase agent 步（phase 内回边）/ `retry` phase fail
 *  后同相位重跑 / `backtrack` 跨相位回跳。词汇本体单点——编排侧 `ChangeStepEdge`
 *  与落库命令（`RunEdgeEntry.edge_kind`）同本类型消费（零映射）。
 */
export type RunEdgeKind = 
/**  计划序推进（相位内按 steps 序推进、相位间推进） */
"forward" | 
/**  gate 失败回到同 phase agent 步（phase 内回边） */
"feedback" | 
/**  phase fail 后同相位重跑 */
"retry" | 
/**  跨相位回跳 */
"backtrack";

/**
 *  变更通知（唯一 IPC 信封；unify-run-state-persistence D3 通知降位）：六
 *  kind-only 变体与 [`RunUpdate`] 一一同型、零载荷——通知仅失效信号，查询
 *  结果权威，客户端收通知自行重查统一视图（`get_change_detail`）与转录库。
 */
export type RunNotice = 
/**  步状态变更（→ 统一视图重查） */
{ ipc: "step" } | 
/**  执行图边变更（→ 统一视图重查） */
{ ipc: "edge" } | 
/**  WorkerAgent 会话事件透传（→ 转录库重查） */
{ ipc: "sessionEvent" } | 
/**  ask 中断（→ 统一视图重查） */
{ ipc: "ask" } | 
/**  phase 间停等确认（→ 统一视图重查） */
{ ipc: "confirmWait" } | 
/**  终态收口（→ 统一视图重查定局） */
{ ipc: "finished" };

/**
 *  run 状态五值（线格式小写词；queries DTO 直接复用本类型）。`interrupted`
 *  仅启动标定产生（重启后 run 客观已死），运行期写路径不产生该值；停等两态
 *  （waitingAsk / waitingConfirm）不落库——应答通道活在进程内。
 */
export type RunStatus = 
/**  运行中（发起建档起步） */
"running" | 
/**  全相位 pass 走完 */
"completed" | 
/**  受控终止（用户停止 / confirm=false / 决策 stop 动作） */
"stopped" | 
/**  失败终止 */
"failed" | 
/**  中断（仅启动标定产生） */
"interrupted";

/**
 *  run 步词汇封闭集（**十九值全词汇**，线格式 snake_case 词）：agent 阶段
 * （executor / evaluator / decision）、脚本阶段（static_check / test_execution /
 *  mutation_test）、流程面步骤（phase_start / phase_log）、三门 gate（verdict_gate、
 *  retry_gate、whitelist_gate）与归档 8 步（preflight / commit / rebase /
 *  resolve_conflicts / merge / spec_sync / seal / finalize）。词汇本体单点——落库命令
 * （`RunNodeEntry.step`）与查询投影（`detail.rs`）同本类型消费，落库零过滤
 * （旧 5 值词表的过滤谓词已退役）。
 */
export type RunStepKind = 
/**  executor 会话 */
"executor" | 
/**  evaluator 会话 */
"evaluator" | 
/**  决策会话 */
"decision" | 
/**  static-check 工具步 */
"static_check" | 
/**  test-execution 门禁工具步 */
"test_execution" | 
/**  mutation-test 门禁工具步 */
"mutation_test" | 
/**  phase-start 相位机步 */
"phase_start" | 
/**  phase-log 相位机步 */
"phase_log" | 
/**  verdict 解析门 */
"verdict_gate" | 
/**  retry 预算门 */
"retry_gate" | 
/**  backtrack 白名单门 */
"whitelist_gate" | 
/**  归档前置只读校验步（内联步） */
"preflight" | 
/**  归档 worktree 提交步（vcs） */
"commit" | 
/**  归档分支重放步（vcs） */
"rebase" | 
/**  归档合入冲突解算步（agent 会话；条件执行） */
"resolve_conflicts" | 
/**  归档主仓快进步（vcs） */
"merge" | 
/**  归档 delta specs 同步步（agent 会话） */
"spec_sync" | 
/**  归档双写收口步（内联步） */
"seal" | 
/**  归档落盘提交步（vcs） */
"finalize";

/**  run 步状态四值（线格式 camelCase 词）。 */
export type RunStepStatus = 
/**  步进行中（收口在途步可留 running） */
"running" | 
/**  步通过 */
"passed" | 
/**  步失败 */
"failed" | 
/**  步因停止 / 终止收敛 */
"stopped";

/**
 *  会话清单分页信封：本页会话 + 过滤集全量计数（页界由 `total` 导出，
 *  不以「页长 === limit」猜下一页）。越界 `offset` 合法空页而 `total` 恒为
 *  过滤集全量（与 db 检视 `RecordsPage` 同口径）。
 */
export type SessionPage = {
	/**  本页会话清单项（`updated_at` 降序稳定序） */
	sessions: SessionSummary[],
	/**  过滤集全量计数（分页前计数，非本页长度） */
	total: number,
};

/**
 *  来源归属：来源受控字符串（debug | explore | …，缺省 debug）+ 来源内定位
 *  （explore 指向探索记录主键的十进制串）。会话级来源，消费方经此寻址。
 */
export type SessionProvenance = {
	/**  来源受控字符串 */
	source: string,
	/**  来源内定位（调试会话为 None） */
	sourceRef: string | null,
};

/**
 *  会话记录契约：id 为 core 铸造 id（字符串主键）；`remote_session_id` 为
 *  引擎侧句柄（双 id 映射的内存半边，落库半边归 store）；`config_snapshot`
 *  为装配配置快照的 JSON 形态（快照不透明——core 不解释装配概念，infra 侧
 *  定型字段面），存快照而非跨库引用。
 */
export type SessionRow = {
	/**  core 铸会话 id（主键） */
	id: string,
	/**  引擎侧句柄（cli / sdk 各自上报的会话标识；未上报为 None） */
	remoteSessionId: string | null,
	/**  装配配置快照（JSON 形态，core 不解释） */
	configSnapshot: unknown,
	/**  来源归属 */
	provenance: SessionProvenance,
	/**  建档时间（UTC unix 毫秒） */
	createdAt: number,
	/**  最近更新时间（UTC unix 毫秒） */
	updatedAt: number,
};

/**
 *  聚合统计：MVP 从轮行 / 转录现算，不维护累计列；统计与查询附带字段缺席
 *  合法缺省（降级不违约）。
 */
export type SessionStats = {
	/**  轮数（轮统计行行数） */
	turnCount: number,
	/**  累计墙钟毫秒（轮行时长求和；全部缺席为 None） */
	totalDurationMs: number | null,
	/**  累计输入 token（TurnDone usage 鸭子类型求和；缺席合法缺省） */
	inputTokens: number | null,
	/**  累计输出 token（TurnDone usage 鸭子类型求和；缺席合法缺省） */
	outputTokens: number | null,
};

/**
 *  会话清单项：会话记录 + 现算聚合统计 + 轮行随行返回（重放部件与历史展示
 *  共用；core 契约类型，不引用 store 模型）。
 */
export type SessionSummary = {
	/**  会话记录 */
	row: SessionRow,
	/**  聚合统计 */
	stats: SessionStats,
	/**  轮统计行（发起顺序） */
	turns: TurnSummary[],
};

/**  测试框架八值枚举（CLI zod enum 同序同串；逐变体显式 rename 对齐 CLI 串） */
export type TestFramework = "jest" | "vitest" | "vite-plus" | "bun" | "rust" | "node-test" | "go" | "pytest";

/**
 *  测试 suite 配置（合法 suite 原样保留 + 默认值填充；`root` / `framework`
 *  非法的 suite 整体剔除并记 diagnostics）
 */
export type TestSuite = {
	/**  suite 锚点路径（相对项目根，非空且无 glob 通配符） */
	root: string,
	/**  测试框架 */
	framework: TestFramework,
	/**  执行目录（相对 root，默认 `.`） */
	cwd: string,
	/**  框架配置文件路径（相对 root；未设为 `None`） */
	config: string | null,
	/**  匹配 glob 列表（相对 root；未设为 `None`） */
	includes: string[] | null,
	/**  排除 glob 列表（相对 root；未设为 `None`） */
	excludes: string[] | null,
	/**  覆盖率阈值（三阈值恒有值） */
	coverage: CoverageThresholds,
	/**  变异测试配置（score 恒有值） */
	mutation: MutationConfig,
};

/**
 *  树条目信封（tag `kind` 判别，`AgentRunMessage` 同式）：目录节点与文件叶
 *  双变体，前端以 `kind` 收窄行形态（目录可展开、文件叶不可）。
 */
export type TreeEntry = 
/**  目录节点（子树聚合统计，可展开） */
{ kind: "dir"; node: DirNode } | 
/**  文件叶（单文件行统计，不可展开） */
{ kind: "file"; node: FileNode };

/**
 *  轮行 DTO（IPC 面）：轮统计行（每轮一行）的契约形态，取代旧 run 记录的
 *  IPC 面。`agent_start` 提前 resolve 返回 running 态行、终态经 Channel 以
 *  同构部件流出、重放按轮序对齐交错——实时与重放两路同构。
 */
export type TurnSummary = {
	/**  轮 id（workspace 库域内自增） */
	turnId: number,
	/**  所属会话 id */
	sessionId: string,
	/**  轮状态（running | completed | failed | stopped） */
	status: AgentRunStatus,
	/**  开始时间（UTC unix 毫秒） */
	startedAt: number,
	/**  结束时间；运行中为 None */
	finishedAt: number | null,
	/**  收敛轮数（来自 TurnDone 事件） */
	numTurns: number | null,
	/**  总成本美元（来自 TurnDone 事件；缺席合法缺省） */
	costUsd: number | null,
	/**  运行时长毫秒（来自 TurnDone 事件；缺席合法缺省） */
	durationMs: number | null,
	/**  失败原因（落库失败收敛 / 无 TurnDone 异常终止时填因） */
	error: string | null,
};

/**  评估 verdict。 */
export type Verdict = "pass" | "fail";

/**
 *  永远合法的完整工作区配置：合法字段原样保留、违例字段吃默认、未知字段
 *  进 `extra`。只序列化方向（组装层 `assemble` 从原文 `Value` 逐字段判定
 *  处置，本类型从不反序列化）。
 */
export type WorkspaceConfig = {
	/**  schema 规则文件引用（线面字段名 `$schema`） */
	$schema: string | null,
	/**  模式标识，固定为 `spec-driven`（未设 / 非法吃默认） */
	schema: string,
	/**  项目上下文描述（未设为 `None`） */
	context: string | null,
	/**  自定义规则配置（未设为 `None`） */
	rules: RulesConfig | null,
	/**  静态分析工具配置（未设为 `None`） */
	staticAnalysis: string | null,
	/**  测试 suite 配置列表（保序；违例 suite 剔除） */
	tests: TestSuite[],
	/**  写入保护配置（未设为 `None`） */
	writeProtection: WriteProtection | null,
	/**  顶层未知字段 passthrough（key + 原文值） */
	extra: ConfigExtraField[],
};

/**
 *  工作区配置报告（命令线面信封）：`config` 永远合法（违例字段以默认值
 *  填充），`diagnostics` 逐条记录文件态 / 违例 / 吃默认项；配置文件缺失以
 *  `fileMissing` 诊断在案（空态标记，非错误）。
 */
export type WorkspaceConfigReport = {
	/**  永远合法的完整配置 */
	config: WorkspaceConfig,
	/**  逐条诊断 */
	diagnostics: ConfigDiagnostic[],
};

/**
 *  user 维度注册表一行（落全局库 `desktop-global.redb`，见 desktop-data-dimensions）：
 *  主键即 `root`（canonical 完整路径）。
 * 
 *  时间戳为 UTC unix 毫秒 `i64`——零解析零格式歧义，且 store 不引入 time 依赖。
 */
export type WorkspaceRecord = {
	/**  canonical 完整路径（主键） */
	root: string,
	/**  目录名最后一段（展示用；完整路径悬停展示） */
	name: string,
	/**  入库时间（UTC unix 毫秒） */
	addedAt: number,
};

/**  写入保护配置。 */
export type WriteProtection = {
	/**  需要保护的文件 glob 模式列表（未设为 `None`） */
	files: WriteProtectionFile[] | null,
};

/**  单条写入保护规则；`glob` 非空串或非字符串的整条剔除并记 diagnostics。 */
export type WriteProtectionFile = {
	/**  文件路径 glob 模式（未设为 `None`） */
	glob: string | null,
	/**  自定义拒绝原因（未设为 `None`） */
	reason: string | null,
};

