    const rows = bodyRows();
    expect(rowCells(rows[0])).toEqual(['1', '1', '']); // 对象行：value 尾列空单元格
    expect(rowCells(rows[1])).toEqual(['2', '', 'null']);
    expect(rowCells(rows[2])).toEqual(['3', '', '[1,2,3]']);
    expect(rowCells(rows[3])).toEqual(['4', '', '"文本"']);
    expect(rowCells(rows[4])).toEqual(['5', '', '42']);
