    expect(headerColumns()).toEqual(['key', 'id', 'name', 'value']);
    const rows = bodyRows();
    expect(rowCells(rows[0])).toEqual(['1', '1', '', '']);
    expect(rowCells(rows[1])).toEqual(['2', '', '', '"退化标量"']);
