    expect(headerColumns()).toEqual(['key', 'id']);
    expect(rowCells(bodyRows()[0])).toEqual(['1', '']); // 缺失键空单元格

    // 对象键恰为 "value"：与非对象行退化列同名合并，不重复追加第二列
    await renderWithModelSelected([
