    ];
    render(<AgentDebugView root={ROOT} />);

    const buttons = within(screen.getByTestId('history-source-filter')).getAllByRole('button');
    fireEvent.click(buttons[2]);
    await waitFor(() =>
      expect(invokeMock).toHaveBeenLastCalledWith('agent_sessions', {
        root: ROOT,
        source: null,
        sourceRef: null,
        offset: 0,
        limit: 20,
