    );
    const rows = await screen.findAllByTestId('agent-run-row');
    expect(rows.map((row) => row.getAttribute('data-session-id'))).toEqual([
      'ses-a-1727000000000',
      'ses-b-1727000000000',
    ]);
  });
});

