    renderDetail(null, list);

    await screen.findByTestId('explore-detail-missing');
    expect(list.updateWorkflowType).not.toHaveBeenCalled();
    expect(invokeMock.mock.calls.map(([name]) => name)).not.toContain('read_explore');
