describe('useExploreSession：send 注入 record.name（AC-4 组装半边）', () => {
  it('正向：新会话首条 send 的 prompt 逐字等于 buildExplorePrompt(input.prompt, record.name)', async () => {
    sessionsResult = [];
    transcript = [];
    const { result } = await mounted();

